contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address caller, address target, uint depositAmount, uint withdrawAmount, bytes calldata data) public payable {
        require(msg.sender != address(c), "test must not be the contract owner");
        require(depositAmount <= address(this).balance, "not enough balance for deposit");

        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;
        uint thisBalanceBefore = address(this).balance;

        (bool depositSuccess, ) = address(c).call{value: depositAmount}("");

        uint depositsAfterDeposit = c.depositsCount();
        uint cBalanceAfterDeposit = address(c).balance;
        uint thisBalanceAfterDeposit = address(this).balance;

        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        uint cBalanceAfterWithdraw = address(c).balance;
        uint thisBalanceAfterWithdraw = address(this).balance;

        bool sendReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        uint cBalanceAfterSend = address(c).balance;
        uint thisBalanceAfterSend = address(this).balance;

        assert(
            (depositSuccess == true) &&
            (depositsAfterDeposit == depositsBefore + 1) &&
            (cBalanceAfterDeposit == cBalanceBefore + depositAmount) &&
            (thisBalanceAfterDeposit == thisBalanceBefore - depositAmount) &&
            (withdrawReverted == true) &&
            (cBalanceAfterWithdraw == cBalanceAfterDeposit) &&
            (thisBalanceAfterWithdraw == thisBalanceAfterDeposit) &&
            (sendReverted == true) &&
            (cBalanceAfterSend == cBalanceAfterWithdraw) &&
            (thisBalanceAfterSend == thisBalanceAfterWithdraw)
        );
    }
}

