contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}
    fallback() external payable {}

    function run(uint depositValue, uint ownerWithdrawValue, uint nonOwnerWithdrawValue) public payable {
        require(address(this).balance >= depositValue, "not enough balance for setup");
        require(nonOwnerWithdrawValue > 0, "non-owner withdraw amount must be positive");

        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Deposit via fallback: send Ether with empty calldata
        (bool depositSuccess, ) = address(c).call{value: depositValue}("");
        require(depositSuccess, "deposit failed");

        uint afterDepositCount = c.depositsCount();
        uint afterDepositBalance = address(c).balance;

        // Owner attempts to send Ether to this test contract
        // This call is made by InvMutTest which is the owner
        bool ownerSendReverted;
        try c.sendMoney(address(this), ownerWithdrawValue, hex"") {
            ownerSendReverted = false;
        } catch {
            ownerSendReverted = true;
        }

        uint afterOwnerSendCount = c.depositsCount();
        uint afterOwnerSendBalance = address(c).balance;

        // Non-owner attempts to withdraw (should always revert)
        // We call from a different address by using a separate call with a different msg.sender?
        // Since the test contract is the owner, we cannot easily change msg.sender without a helper.
        // However, we can use c.withdraw from this contract (owner) — that would succeed if enough balance.
        // To test non-owner revert, we need to call from a non-owner address.
        // We cannot do that directly here. Instead, we can check that onlyOwner works by calling withdraw
        // from this contract? But this contract is the owner.
        // We need a different approach: we can deploy another contract? Not allowed (no new deployments).
        // We cannot change msg.sender for the call to c.
        // So we cannot test non-owner revert with a direct call.
        // We must drop the non-owner revert part and focus on what we can observe.

        // Let's simplify: after deposit, only owner can withdraw. Since we are owner, a withdraw should succeed.
        // But we want a general rule. Let's make the rule: deposit increases count and balance, owner send does not change count.
        // Also, owner withdraw reduces balance by the withdrawn amount (if enough) and does not change count.

        // We'll do an owner withdraw as well.
        bool ownerWithdrawReverted;
        try c.withdraw(ownerWithdrawValue) {
            ownerWithdrawReverted = false;
        } catch {
            ownerWithdrawReverted = true;
        }

        uint afterOwnerWithdrawCount = c.depositsCount();
        uint afterOwnerWithdrawBalance = address(c).balance;

        assert(
            afterDepositCount == beforeCount + 1 &&
            afterDepositBalance == beforeBalance + depositValue &&
            afterOwnerSendCount == afterDepositCount &&
            !ownerSendReverted &&
            (ownerWithdrawValue <= afterOwnerSendBalance ? (!ownerWithdrawReverted && afterOwnerWithdrawBalance == afterOwnerSendBalance - ownerWithdrawValue) : (ownerWithdrawReverted && afterOwnerWithdrawBalance == afterOwnerSendBalance)) &&
            afterOwnerWithdrawCount == afterOwnerSendCount
        );
    }
}

