contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint depositAmount, uint sendAmount) public payable {
        require(depositAmount > 0, "deposit must be positive");
        require(sendAmount > 0, "send amount must be positive");
        require(address(this).balance >= depositAmount + sendAmount, "insufficient balance");

        // Send Ether directly to C's fallback, increasing C's balance and depositsCount.
        c.depositsCount(); // view call to warm up; no state change
        uint beforeCount = c.depositsCount();

        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit, "deposit failed");

        uint afterDepositCount = c.depositsCount();
        require(afterDepositCount == beforeCount + 1, "depositsCount must increase by 1 per fallback");

        uint balanceAfterDeposit = address(c).balance;

        // As owner (msg.sender is the InvMutTest contract, and C's owner is msg.sender at deployment),
        // use sendMoney to forward sendAmount to a recipient (the zero address).
        // This is a state-changing call that must be a top-level statement.
        c.sendMoney(address(0), sendAmount, "");

        assert(address(c).balance == balanceAfterDeposit - sendAmount);
    }

    receive() external payable {}
}

